function f(t){return t?new Date(t).toLocaleString("en-IN",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}):"—"}function u(t){if(!t)return"—";const e=new Date(t).getTime()-Date.now(),n=Math.round(e/6e4),o=Math.abs(n),a=new Intl.RelativeTimeFormat("en",{numeric:"auto"});if(o<60)return a.format(n,"minute");const r=Math.round(n/60);if(Math.abs(r)<24)return a.format(r,"hour");const i=Math.round(r/24);return a.format(i,"day")}function s(t){if(!t)return!1;const e=new Date(t),n=new Date;return e.getFullYear()===n.getFullYear()&&e.getMonth()===n.getMonth()&&e.getDate()===n.getDate()}function c(t){const e=Math.floor((new Date(t).getTime()-Date.now())/1e3);return Math.max(0,e)}export{u as a,f,s as i,c as s};
